+)
+
+func TestNormalizeSemver(t *testing.T) {
+	t.Parallel()
+
+	cases := []struct {
+		in, want string
+	}{
+		{"", "v0.0.0"},
+		{"dev", "v0.0.0"},
+		{"0.5.3", "v0.5.3"},
+		{"v0.5.3", "v0.5.3"},
+		{"  1.2.3  ", "v1.2.3"},
+		{"0.5.3-rc.1", "v0.5.3-rc.1"},
